<!DOCTYPE html>
<html lang="pt-BR">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Matheus & Julia 💕</title>
<link href="https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,400;0,700;1,400&family=Inter:wght@300;400;500;600&display=swap" rel="stylesheet">
<style>
  :root {
    --rose: #c0435a;
    --rose-dark: #8b2c40;
    --rose-light: #e8899a;
    --deep: #1a0a0e;
    --card-bg: #2a1520;
    --card-border: #5a2535;
    --text: #f5e6ea;
    --muted: #b08090;
    --purple: #9b59b6;
    --gold: #d4a843;
    --blue: #5b7fc4;
  }
  * { margin: 0; padding: 0; box-sizing: border-box; }
  body { font-family: 'Inter', sans-serif; background: var(--deep); color: var(--text); min-height: 100vh; overflow-x: hidden; }

  /* Particles */
  #particles { position: fixed; top: 0; left: 0; width: 100%; height: 100%; pointer-events: none; z-index: 0; }
  .hp { position: absolute; opacity: 0; animation: floatUp linear infinite; pointer-events: none; }
  @keyframes floatUp {
    0%   { transform: translateY(100vh) rotate(0deg); opacity: 0; }
    10%  { opacity: 0.6; }
    90%  { opacity: 0.3; }
    100% { transform: translateY(-100px) rotate(360deg); opacity: 0; }
  }

  /* Edit banner */
  #edit-banner {
    position: fixed; top: 0; left: 0; right: 0;
    background: linear-gradient(90deg, var(--purple), var(--rose));
    color: #fff; padding: 10px 20px;
    display: flex; align-items: center; justify-content: space-between;
    z-index: 1000; font-size: 14px; font-weight: 500;
    transform: translateY(-100%); transition: transform .3s;
  }
  #edit-banner.active { transform: translateY(0); }
  #edit-banner button { background: #fff; color: var(--rose-dark); border: none; padding: 6px 14px; border-radius: 20px; cursor: pointer; font-weight: 600; font-size: 13px; }

  /* FAB */
  #fab-edit {
    position: fixed; bottom: 30px; right: 30px;
    width: 56px; height: 56px;
    background: linear-gradient(135deg, var(--rose), var(--purple));
    border-radius: 50%; border: none; cursor: pointer;
    font-size: 22px; color: #fff;
    box-shadow: 0 4px 20px rgba(192,67,90,.5);
    z-index: 999; transition: transform .2s, box-shadow .2s;
    display: flex; align-items: center; justify-content: center;
  }
  #fab-edit:hover { transform: scale(1.1); box-shadow: 0 6px 25px rgba(192,67,90,.7); }

  /* Audio FAB */
  #audio-fab {
    position: fixed; bottom: 100px; right: 30px;
    width: 48px; height: 48px;
    background: var(--card-bg); border: 1px solid var(--card-border);
    border-radius: 50%; cursor: pointer;
    font-size: 20px; color: var(--rose-light);
    box-shadow: 0 2px 12px rgba(0,0,0,.4);
    z-index: 998; transition: all .2s;
    display: flex; align-items: center; justify-content: center;
  }
  #audio-fab:hover { background: var(--card-border); }
  #audio-fab.playing { color: var(--gold); border-color: var(--gold); animation: pulse 1.5s infinite; }
  @keyframes pulse { 0%,100%{box-shadow:0 0 0 0 rgba(212,168,67,.4)} 50%{box-shadow:0 0 0 8px rgba(212,168,67,0)} }

  /* Audio Modal */
  #audio-modal {
    position: fixed; inset: 0;
    background: rgba(0,0,0,.75); z-index: 3000;
    display: none; align-items: center; justify-content: center;
    backdrop-filter: blur(6px); padding: 20px;
  }
  #audio-modal.open { display: flex; }
  .amodal-box {
    background: #1e0f15; border: 1px solid var(--card-border);
    border-radius: 24px; padding: 30px; width: 100%; max-width: 380px; text-align: center;
  }
  .amodal-box h3 { font-family: 'Playfair Display', serif; font-size: 20px; margin-bottom: 8px; }
  .amodal-box p { color: var(--muted); font-size: 13px; margin-bottom: 24px; }
  #drop-zone {
    border: 2px dashed var(--card-border); border-radius: 18px;
    padding: 36px 20px; cursor: pointer; transition: all .2s; margin-bottom: 16px;
    position: relative;
  }
  #drop-zone:hover, #drop-zone.over { border-color: var(--rose-light); background: rgba(192,67,90,.08); }
  #drop-zone .dz-icon { font-size: 40px; margin-bottom: 10px; display: block; }
  #drop-zone .dz-text { color: var(--muted); font-size: 14px; line-height: 1.5; }
  #drop-zone .dz-text strong { color: var(--rose-light); }
  #audio-file-input { position: absolute; inset: 0; opacity: 0; cursor: pointer; width: 100%; height: 100%; }
  #audio-filename { background: var(--card-bg); border-radius: 12px; padding: 10px 14px; font-size: 13px; color: var(--rose-light); display: none; margin-bottom: 16px; word-break: break-all; }
  #btn-close-audio { background: none; border: 1px solid var(--card-border); color: var(--muted); padding: 10px 24px; border-radius: 20px; cursor: pointer; font-size: 14px; width: 100%; }
  #btn-close-audio:hover { border-color: var(--rose-light); color: var(--rose-light); }

  /* Generic overlay + panel */
  #overlay { position: fixed; inset: 0; background: rgba(0,0,0,.7); z-index: 1999; display: none; backdrop-filter: blur(4px); }
  #overlay.open { display: block; }
  #edit-panel {
    position: fixed; top: 50%; left: 50%;
    transform: translate(-50%,-50%) scale(.95);
    background: #1e0f15; border: 1px solid var(--card-border);
    border-radius: 24px; padding: 30px; width: 90%; max-width: 400px;
    z-index: 2000; display: none; opacity: 0; transition: all .3s;
    box-shadow: 0 30px 80px rgba(0,0,0,.8);
  }
  #edit-panel.open { display: block; opacity: 1; transform: translate(-50%,-50%) scale(1); }
  .ep-title { font-family: 'Playfair Display', serif; font-size: 20px; margin-bottom: 24px; color: #fff; }
  .ep-field { margin-bottom: 16px; }
  .ep-field label { display: block; font-size: 11px; letter-spacing: 2px; text-transform: uppercase; color: var(--muted); margin-bottom: 8px; }
  .ep-field input, .ep-field textarea {
    width: 100%; background: var(--card-bg); border: 1px solid var(--card-border);
    border-radius: 12px; padding: 12px 16px; color: #fff;
    font-size: 14px; font-family: 'Inter', sans-serif; outline: none; transition: border-color .2s;
  }
  .ep-field input:focus, .ep-field textarea:focus { border-color: var(--rose-light); }
  .ep-field textarea { resize: vertical; min-height: 100px; line-height: 1.6; }
  .ep-actions { display: flex; gap: 10px; margin-top: 20px; }
  #btn-ep-save { flex: 1; background: linear-gradient(135deg, var(--rose), var(--rose-dark)); color: #fff; border: none; padding: 14px; border-radius: 14px; font-weight: 600; cursor: pointer; font-size: 15px; }
  #btn-ep-cancel { background: var(--card-bg); color: var(--muted); border: 1px solid var(--card-border); padding: 14px 20px; border-radius: 14px; cursor: pointer; font-size: 15px; }

  /* Main */
  #main { position: relative; z-index: 1; }

  /* Hero */
  #hero { min-height: 100vh; display: flex; flex-direction: column; align-items: center; justify-content: center; padding: 40px 20px; }

  .music-card { background: var(--rose-dark); border-radius: 24px; padding: 20px; width: 100%; max-width: 360px; box-shadow: 0 20px 60px rgba(0,0,0,.6); margin-bottom: 30px; }
  .mc-header { display: flex; align-items: center; justify-content: space-between; margin-bottom: 16px; font-size: 13px; color: rgba(255,255,255,.8); font-weight: 600; }
  .mc-photo { width: 100%; aspect-ratio: 1; border-radius: 16px; overflow: hidden; position: relative; margin-bottom: 16px; background: #5a2535; cursor: pointer; }
  .mc-photo img { width: 100%; height: 100%; object-fit: cover; display: none; }
  .mc-photo img.loaded { display: block; }
  .mc-photo .ph { position: absolute; inset: 0; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 12px; color: var(--rose-light); font-size: 14px; text-align: center; padding: 20px; }
  .mc-photo .ph span { font-size: 40px; }
  .mc-song { font-size: 15px; font-weight: 700; color: #fff; margin-bottom: 4px; }
  .mc-artist { font-size: 13px; color: rgba(255,255,255,.7); margin-bottom: 14px; }
  .mc-prog { height: 3px; background: rgba(255,255,255,.2); border-radius: 2px; overflow: hidden; }
  .mc-prog-bar { height: 100%; background: #fff; width: 30%; border-radius: 2px; animation: prog 8s linear infinite; }
  @keyframes prog { 0%{width:5%} 100%{width:95%} }

  .hero-names { font-family: 'Playfair Display', serif; font-size: clamp(36px,8vw,64px); font-weight: 700; text-align: center; line-height: 1.1; margin-bottom: 8px; }
  .hero-names .accent { color: var(--rose-light); }
  .hero-tagline { font-size: 14px; color: var(--muted); text-align: center; letter-spacing: 2px; text-transform: uppercase; margin-bottom: 40px; }

  /* Sections */
  .sec { padding: 60px 20px; max-width: 480px; margin: 0 auto; }
  .sec-label { font-size: 11px; letter-spacing: 3px; text-transform: uppercase; color: var(--rose-light); margin-bottom: 20px; display: flex; align-items: center; gap: 10px; }
  .sec-label::after { content: ''; flex: 1; height: 1px; background: var(--card-border); }

  /* Photos */
  #sec-photos { padding: 60px 20px; max-width: 600px; margin: 0 auto; }
  .photo-grid { display: grid; grid-template-columns: repeat(2,1fr); gap: 12px; margin-top: 20px; }
  .pslot { aspect-ratio: 1; border-radius: 16px; overflow: hidden; position: relative; background: var(--card-bg); border: 1px dashed var(--card-border); cursor: pointer; transition: all .2s; }
  .pslot:hover { border-color: var(--rose-light); }
  .pslot img { width: 100%; height: 100%; object-fit: cover; display: none; }
  .pslot.has-photo img { display: block; }
  .pslot.has-photo .padd { display: none; }
  .padd { position: absolute; inset: 0; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 8px; color: var(--muted); font-size: 12px; }
  .padd span { font-size: 28px; }

  /* Counter */
  .counter-card { background: var(--card-bg); border: 1px solid var(--card-border); border-radius: 24px; padding: 30px 24px; }
  .counter-together { font-size: 13px; color: var(--muted); text-align: center; margin-bottom: 20px; }
  .counter-together strong { color: var(--rose-light); }
  .cg { display: grid; grid-template-columns: repeat(3,1fr); gap: 12px; margin-bottom: 12px; }
  .ci { background: rgba(255,255,255,.05); border-radius: 16px; padding: 20px 10px; text-align: center; }
  .cn { font-family: 'Playfair Display', serif; font-size: 36px; font-weight: 700; color: #fff; line-height: 1; margin-bottom: 6px; }
  .cl { font-size: 11px; color: var(--muted); text-transform: uppercase; letter-spacing: 1px; }
  #btn-change-date { background: var(--card-bg); border: 1px solid var(--card-border); color: var(--muted); padding: 10px 20px; border-radius: 20px; cursor: pointer; font-size: 13px; display: block; margin: 16px auto 0; }
  #btn-change-date:hover { border-color: var(--rose-light); color: var(--rose-light); }

  /* Message */
  .msg-card { background: var(--blue); border-radius: 24px; padding: 28px 24px; position: relative; overflow: hidden; }
  .msg-card::before { content: '❝'; position: absolute; top: -10px; left: 20px; font-size: 80px; color: rgba(255,255,255,.1); line-height: 1; font-family: Georgia,serif; }
  .msg-badge { font-size: 11px; letter-spacing: 3px; text-transform: uppercase; color: rgba(255,255,255,.7); margin-bottom: 16px; }
  .msg-title { font-family: 'Playfair Display', serif; font-size: 20px; font-weight: 700; color: #fff; line-height: 1.4; margin-bottom: 20px; position: relative; z-index: 1; }
  .msg-body { font-size: 14px; color: rgba(255,255,255,.85); line-height: 1.7; display: none; margin-bottom: 16px; position: relative; z-index: 1; }
  .msg-body.vis { display: block; }
  #btn-msg { background: #fff; color: var(--blue); border: none; padding: 12px 24px; border-radius: 30px; font-weight: 600; font-size: 14px; cursor: pointer; position: relative; z-index: 1; }

  /* Achievements */
  .ach-grid { display: grid; grid-template-columns: repeat(4,1fr); gap: 10px; margin-top: 16px; }
  .ach { background: var(--card-bg); border: 1px solid var(--card-border); border-radius: 14px; aspect-ratio: 1; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 6px; font-size: 22px; color: var(--rose-light); cursor: pointer; transition: all .2s; position: relative; }
  .ach.on { border-color: var(--purple); }
  .ach.on::after { content: ''; position: absolute; inset: -1px; border-radius: 14px; background: linear-gradient(135deg,var(--purple),var(--rose)); z-index: -1; }
  .ach.off { opacity: .4; }
  .ach-name { font-size: 9px; color: var(--muted); text-align: center; padding: 0 4px; line-height: 1.2; }
  #ach-count { font-size: 12px; color: var(--muted); text-align: right; margin-bottom: 10px; }

  /* Contenteditable */
  [contenteditable="true"] { outline: none; cursor: text; border-radius: 4px; transition: background .2s; }
  body.editing [contenteditable="true"] { background: rgba(192,67,90,.1); outline: 1px dashed var(--rose-light); padding: 2px 4px; }

  /* Reveal */
  .reveal { opacity: 0; transform: translateY(30px); transition: opacity .6s, transform .6s; }
  .reveal.vis { opacity: 1; transform: none; }

  footer { text-align: center; padding: 40px 20px; color: var(--muted); font-size: 13px; position: relative; z-index: 1; }
  footer .h { color: var(--rose-light); }

  @media (max-width:400px) { .cn { font-size: 28px; } .ach-grid { grid-template-columns: repeat(3,1fr); } }
</style>
</head>
<body>

<div id="particles"></div>

<!-- Edit Banner -->
<div id="edit-banner">
  ✏️ Modo de Edição — clique nos textos para editar
  <button id="btn-banner-save">Salvar</button>
</div>

<!-- Overlay + Date Panel -->
<div id="overlay"></div>
<div id="edit-panel">
  <h3 class="ep-title">📅 Data de início</h3>
  <div id="panel-fields">
    <div class="ep-field">
      <label>Data e hora do início do relacionamento</label>
      <input type="datetime-local" id="input-start-date" value="2026-05-23T20:00">
    </div>
  </div>
  <div class="ep-actions">
    <button id="btn-ep-cancel">Cancelar</button>
    <button id="btn-ep-save">Salvar ✓</button>
  </div>
</div>

<!-- Audio Modal -->
<div id="audio-modal">
  <div class="amodal-box">
    <h3>🎵 Música de fundo</h3>
    <p>Selecione um arquivo de áudio do seu dispositivo</p>
    <label id="drop-zone" for="audio-file-input">
      <span class="dz-icon">🎶</span>
      <div class="dz-text"><strong>Toque aqui para escolher</strong><br>MP3, M4A, OGG, WAV…</div>
    </label>
    <input type="file" id="audio-file-input" accept="audio/*" style="display:none">
    <div id="audio-filename"></div>
    <button id="btn-close-audio">Fechar</button>
  </div>
</div>

<!-- Audio FAB -->
<button id="audio-fab" title="Música">🎵</button>
<!-- Player nativo visível como fallback -->
<audio id="bg-audio" loop src="data:audio/aac;base64,